import { useGesture } from '@use-gesture/react';
import clsx from 'clsx';
import React, { useLayoutEffect } from 'react';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { svgPlotLayout } from '../../../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useGridPlotSize } from '../../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { useKeyboardControls } from '../../../../core/components/overlays/hooks/useKeyboardControls.js';
import { usePanning } from '../../../../core/components/zoom/hooks/usePanning.js';
import { resizeCursor } from '../../../../core/components/zoom/ZoomCursors.sty.js';
import {
  useCurrentDomainState,
  useSetState,
  useZoomState,
} from '../../../hooks/store/selectors.js';
import { useHistogramInteractions } from '../../../hooks/useHistogramInteractions.js';
import { useHistogramXScale } from '../../../hooks/useHistogramXScale.js';
import { leftMouseClick, middleMouseClick } from '../constants.js';
import { brushOverlay } from '../HistogramOverlays.sty.js';
import { usePanningKeyboardMovementHandlers } from '../hooks/usePanningKeyboardMovementHandlers.js';

export const HistogramPanMode = () => {
  const plotRef = React.useRef<SVGRectElement>(null);
  const { width, height } = useGridPlotSize();
  const { xScale, initialXScale } = useHistogramXScale();
  const { onZoomChange, pan } = useHistogramInteractions();
  const setState = useSetState();
  const { keyboardPanning } = usePanningKeyboardMovementHandlers();
  const { activeKeyboardMode } = useZoomState();
  const currentDomain = useCurrentDomainState();
  const isChartWithZoom = Boolean(currentDomain);
  const isPanEnabled = pan?.enabled && isChartWithZoom;

  function handlePan(domain: number[]) {
    setState((prev) => ({
      ...prev,
      currentDomain: domain,
    }));
  }

  function handlePanEnd([min, max]: number[]) {
    onZoomChange?.(min, max, 'panning');
  }

  const { onDrag, onDragEnd, onWheel, onWheelEnd } = usePanning({
    initialXScale,
    xScale,
    onPanning: handlePan,
    onPanningEnd: handlePanEnd,
  });

  useGesture(
    {
      onDrag,
      onDragEnd,
      onWheel,
      onWheelEnd,
    },
    {
      target: plotRef,
      eventOptions: { passive: false },
      drag: {
        filterTaps: true,
        pointer: { buttons: [leftMouseClick, middleMouseClick] },
      },
      enabled: isPanEnabled,
    },
  );

  const handleCancel = () => {
    setState((prev) => ({
      ...prev,
      zoom: {
        ...prev.zoom,
        keyboardFocusMode: prev.zoom.activeKeyboardMode,
        activeKeyboardMode: undefined,
      },
    }));
  };

  useKeyboardControls({
    ref: plotRef,
    onLeft: keyboardPanning('left'),
    onRight: keyboardPanning('right'),
    onCancel: handleCancel,
  });

  useLayoutEffect(() => {
    if (activeKeyboardMode === 'panning') {
      plotRef.current?.focus();
    }
  });

  return isPanEnabled ? (
    <svg className={clsx(svgPlotLayout, brushOverlay, resizeCursor)}>
      <rect
        ref={plotRef}
        x={0}
        y={0}
        width={width}
        height={height}
        fill="transparent"
        stroke={`${Colors.Border.Neutral.Default}`}
        tabIndex={activeKeyboardMode === 'panning' ? 0 : undefined}
        data-testid="panning-overlay"
      />
    </svg>
  ) : null;
};
